package com.silverguardian.prototype.reminder;
import android.content.*;import com.silverguardian.prototype.data.Repository;import com.silverguardian.prototype.models.Medicine;import com.silverguardian.prototype.models.User;
public class BootReceiver extends BroadcastReceiver{@Override public void onReceive(Context c,Intent i){if(!Intent.ACTION_BOOT_COMPLETED.equals(i.getAction()))return;TtsHelper.init(c);Repository r=Repository.init(c);for(User u:r.getUsers()){r.setActiveUser(u.id);for(Medicine m:r.getMedicines())MedicineAlarmScheduler.schedule(c,u.id,u.name,m);}DailyCareReceiver.schedule(c);}}